{
  "spans": [
    {
      "label": "QUOTE",
      "head": "ཐིམ་དང་ལོངས་སྤྱོད་བདག་པོ་ཡི། ། རྩ་བ་བདུན་ཅུ་རྩ་གཉིས་པོ། ། ཕྱོགས་གསུམ་ནང་དུ་སྡུད་པ་ཡིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དེ་ལྟར་འཁོར་ལོ་རྩ་ཆེན་རྣམས། ། བསྐམས་ཏེ་རླུང་རྣམས་མི་རྒྱུ་བ། ། དེ་ནས་ཞག་གཅིག་ནས་འཕོའོ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "དང་པོ་(བསྟན་)ནི།",
      "head": "རླུང་གི་སྡུད་རིམ་བསྟན་པ་ནི། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "རླུང་བཅུ་ཟླ་བཅུ་ནས་རྫོགས་ཏེ། ། སྐྱེས་ནས་དུས་སུ་འཆི་བ་གང་། ། ལོ་ནི་བཅུ་བཅུ་རིམ་པ་ལྟར། ། ནོར་རྒྱལ་ལྷ་སྦྱིན་རྩངས་རུས་སྦལ། ། ཀླུ་དང་ཁྱབ་བྱེད་མཉམ་གནས་དང་། ། གྱེན་རྒྱུ་ཐུར་སེལ་སྲོག་རླུང་གི །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྡོ་རྗེ་འཕྲེང་བར་གསུངས།",
      "head": "སྟོབས་རྣམས་གཅིག་ལ་གཅིག་ཐིམ་པར། ། འགྱུར་ཞེས་རྡོ་རྗེ་འཕྲེང་བར་གསུངས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "དུས་ཀྱི་འཁོར་ལོ་ལས།",
      "head": "རྒྱས་པར་དུས་ཀྱི་འཁོར་ལོ་ལས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "སྐྱེས་བུ་ཚེ་ལོ་བརྒྱ་པ་གང་། ། སྐྱེས་ནས་ལོ་གཅིག་རླུང་རྣམས་ཀྱི། ། དུས་སྦྱོར་གྲངས་ཀུན་མཉམ་པར་རྒྱུ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དེ་ནས་བགྲོད་པ་གསུམ་པ་ལ། ། མཁའ་རུ་རླུང་གཅིག་རྒྱུ་བ་འཕེལ། ། བགྲོད་པ་བཞི་པར་འཕེལ་འགྲིབ་མེད། ། ལོ་གཉིས་པ་ལ་ས་རླུང་དུ། ། གཡས་པར་རླུང་གཉིས་འཕེལ་བ་ཡིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དེ་ལྟར་རེ་མོས་རེ་རེ་འཕེལ། ། ཕྱོགས་གསུམ་མ་ཚང་ལོ་བདུན་ན། ། ཆུ་སྲང་གཅིག་འགྱུར་དེ་ནས་ནི། ། གཡོན་དང་གཡས་སུ་རིམ་པ་བཞིན། ། ལོ་རེ་ཆུ་སྲང་རེ་རེ་འཕེལ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དྲུག་ཅུ་རྩ་བདུན་ལོན་ནས་ནི། ། ཆུ་ཚོད་གཅིག་འགྱུར་གཡོན་ནས་རྒྱུ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དེ་ནས་བགྲོད་པ་རེ་རེ་བཞིན། ། ལོ་ནི་སུམ་ཅུར་དབྱུག་གུ་འཕེལ། ། གཡོན་དང་གཡས་པ་རིམ་པ་བཞིན། ། མཁའ་དང་ས་རླུང་གནས་དེར་འབྱུང་། ། དགུ་བཅུ་གོ་དྲུག་ཟླ་བ་ནི། ། བཅུ་གཅིག་ལོན་ནས་གཡོན་དུ་ནི། ། ནམ་མཁའི་རང་བཞིན་ཞག་གཅིག་རྒྱུ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དེ་ནས་ལོ་གསུམ་ཕྱོགས་གསུམ་ན། ། འཕོ་བར་འགྱུར་བ་ལོ་བརྒྱ་ཡིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ད་ནི་ལོ་གསུམ་ཕྱོགས་གསུམ་གྱི། ། དབུ་མའི་འཆི་ལྟས་ངེས་པ་ནི། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཟླ་བ་སོ་བདུན་ཕྱེད་བཅས་ལ། ། ཞག་གི་འཕེལ་བ་སོ་གསུམ་སྟེ། ། སོ་བཞི་ཕྱེད་བཅས་ཞག་གྲངས་ལ། ། རེ་རེ་འཕེལ་འགྱུར་སུམ་ཅུའི་བར། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ལྟེ་བའི་ཁྱིམ་གྱི་རྩ་དྲུག་ཅུ། ། གཡོན་དུ་མཁའ་ནས་རིམ་པ་ལྟར། ། གསུམ་གསུམ་གྱིས་ནི་རྩ་དྲུག་དྲུག ། བསྐམས་ཤིང་མི་མཉམ་རྒྱུ་བ་འཕེལ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དེ་བཞིན་གཡས་ནས་མཉམ་པ་རུ། ། གཉིས་བཞི་ལ་སོགས་ས་རླུང་ནས། ། སྡུད་རིམ་འགག་ཅིང་ཁྱིམ་དྲུག་སྟོང་། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དེ་རྗེས་ཟླ་བ་གསུམ་པོ་ལ། ། གཡོན་ནས་སོ་གཅིག་སྙིང་སྟོབས་ཟད། ། གཡས་ནས་སོ་གཉིས་རྡུལ་ཟད་བྱེད། ། རྩ་བའི་རྩ་ཆེན་དྲུག་དྲུག་འགག ། དེ་རྗེས་སོ་གསུམ་རླུང་ཀུན་ཟད། ། མུན་པ་ཆེན་པོ་ཟད་བྱེད་རླུང་། ། ཞག་གཅིག་རྒྱུ་ཞིང་འཕོ་བར་བྱེད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "སོ་གཉིས་ཕྱེད་བཅས་ཀྱིས་བགོས་པས། ། དབུ་མའི་འཆི་ལྟས་ངེས་པ་ཡིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དེ་ནས་དུས་མིན་ཉི་མ་ཡི། ། འཆི་ལྟས་ངེས་པ་འདི་ལྟ་སྟེ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "གཡས་སུ་ཞག་གཅིག་རྒྱུ་བ་ནི། ། ལོ་གསུམ་ཕྱོགས་གསུམ་ན་འཆིའོ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ལྔ་རྒྱུ་ལོ་གསུམ་ཚེ་ཡིན་ཏེ། ། བཅུ་རྒྱུ་ལོ་གཉིས་ཚེ་ཡིན་ནོ། ། བཅོ་ལྔ་རྒྱུ་ན་ལོ་གཅིག་ཚེ། ། ཉི་ཤུ་རྒྱུ་ན་ཟླ་དྲུག་འཚོ། ། ཉེར་ལྔ་རྒྱུ་ན་ཟླ་བ་གསུམ། ། དེ་རྣམས་ལྔ་ཚན་འཕེལ་བ་སྟེ། ། ཁྱིམ་ལྔ་སྟོང་པར་འགྱུར་བ་ཡིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དེ་ནས་རེ་རེས་ཁྱིམ་རེ་འདོར། ། ཉེར་དྲུག་རྒྱུ་བས་ཟླ་གཉིས་ཚེ། ། ཉེར་བདུན་རྒྱུ་བས་ཟླ་གཅིག་ཐུབ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཁྱིམ་བདུན་འདས་ནས་རྒྱས་པ་སྟེ། ། དེ་ནས་སུས་ཀྱང་བཟློག་མི་ནུས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཞག་ནི་སོ་གསུམ་ན་འཆི་བ། ། བཅོ་ལྔ་བཅུ་དང་ལྔ་དང་གསུམ། ། ཁྱིམ་བཞི་འདོར་བྱེད་བཅུ་གཅིག་སྟོང་། ། ཉི་མའི་སྟོབས་ཟད་. . . . . . . . . . . . .། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": ". . . . . . . . . . . .དེ་འོག་ཏུ། ། ཟླ་བ་ཟད་པར་བྱེད་པའི་རླུང་། ། གཡོན་ནས་ཞག་གཉིས་རྒྱུ་བར་བྱེད། ། ཁྱིམ་ནི་བཅུ་གཉིས་པ་ཡང་སྟོངས། ། དེ་ནས་དབུ་མར་ཞག་གཅིག་རྒྱུ། ། རྣམ་ཤེས་ཕ་རོལ་འགྲོ་བར་བྱེད། །",
      "tail": ""
    }
  ]
}
